from docx import Document
doc = Document('/app/Interview_Assessment_Report_John_Smith.docx')
print('=== JOHN SMITH REPORT ===')
for p in doc.paragraphs:
    if p.text.strip():
        for r in p.runs:
            attrs = ''
            if r.font.name: attrs += f'name={r.font.name} '
            if r.font.size: attrs += f'size={r.font.size} '
            if r.bold: attrs += 'B '
            if r.italic: attrs += 'I '
        print(f'[{p.alignment}] {p.text[:100]}...' if len(p.text) > 100 else f'[{p.alignment}] {p.text}')
print('\n--- TABLE ---')
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            # Get shading
            tcPr = cell._tc.tcPr
            fill = None
            valign = None
            if tcPr:
                for child in tcPr:
                    tag = child.tag.split('}')[-1]
                    if tag == 'shd':
                        fill = child.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}fill')
                    if tag == 'vAlign':
                        valign = child.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val')
            print(f'  [{cell.text}] fill={fill} valign={valign}')
